@namespace sv_f196e7562c6d441981ec843a2c602f4c.Components.Pages.Apply

<nav class="d-flex justify-content-between align-items-center mb-4 position-relative">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i;
        var isCompleted = step < CurrentStep;
        var isCurrent = step == CurrentStep;
        var isFuture = step > CurrentStep;

        <div class="text-center flex-fill position-relative" style="z-index: 1;">
            <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepClass(step)"
                    style="width: 40px; height: 40px; font-size: 0.85rem;"
                    disabled="@isFuture"
                    @onclick="() => OnStepClicked(step)">
                @if (isCompleted)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </button>
            <div class="mt-1 small @(isFuture ? "text-muted" : isCurrent ? "fw-bold" : "")">
                @StepNames[step]
            </div>
        </div>
    }
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private string StepClass(int step)
    {
        if (step < CurrentStep) return "btn-success";
        if (step == CurrentStep) return "btn-primary";
        return "btn-outline-secondary";
    }

    private async Task OnStepClicked(int step)
    {
        if (step < CurrentStep)
            await OnStepSelected.InvokeAsync(step);
    }
}

@namespace sv_f196e7562c6d441981ec843a2c602f4c.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync(Index)">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name</label>
                <input class="form-control" value="@Entry.Company"
                       @onchange="e => Update(Entry with { Company = (string?)e.Value ?? string.Empty })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title</label>
                <input class="form-control" value="@Entry.Title"
                       @onchange="e => Update(Entry with { Title = (string?)e.Value ?? string.Empty })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date</label>
                <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                       @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                       disabled="@IsCurrent"
                       @onchange="e => Update(Entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="@($"current-{Index}")"
                           checked="@IsCurrent"
                           @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"current-{Index}")">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="2" value="@Entry.Description"
                          @onchange="e => Update(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<(int Index, WorkEntry Entry)> OnChanged { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null;

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        Update(updated);
    }

    private async Task Update(WorkEntry updated)
    {
        await OnChanged.InvokeAsync((Index, updated));
    }
}

