@namespace sv_f196e7562c6d441981ec843a2c602f4c.Components.Pages.Apply

<h5 class="mb-3">Personal Information</h5>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input class="form-control" value="@FullName"
               @onchange="e => FullName = (string?)e.Value ?? string.Empty" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control @(emailInvalid ? "is-invalid" : "")" value="@Email"
               @onchange="e => { Email = (string?)e.Value ?? string.Empty; emailInvalid = false; }" />
        @if (emailInvalid)
        {
            <div class="invalid-feedback">Please enter a valid email address.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control" value="@Phone"
               @onchange="e => Phone = (string?)e.Value ?? string.Empty" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input class="form-control" value="@Address"
               @onchange="e => Address = (string?)e.Value ?? string.Empty" />
    </div>
</div>

<div class="mt-4 d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
        @if (isValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public PersonalInfo? Model { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName = string.Empty;
    private string Email = string.Empty;
    private string Phone = string.Empty;
    private string Address = string.Empty;
    private string? ErrorMessage;
    private bool emailInvalid;
    private bool isValidating;

    protected override void OnParametersSet()
    {
        if (Model is not null)
        {
            FullName = Model.FullName;
            Email = Model.Email;
            Phone = Model.Phone;
            Address = Model.Address;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        emailInvalid = false;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(Email);
            if (!valid)
