@page "/apply"
@namespace sv_f196e7562c6d441981ec843a2c602f4c.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_f196e7562c6d441981ec843a2c602f4c.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h3 class="mb-4">Job Application</h3>

    <StepIndicator CurrentStep="currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo"
                              ApplicationService="ApplicationService"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        OnBack="GoBack"
                        OnEditSection="GoToStep"
                        OnSubmit="HandleSubmit"
                        IsSubmitting="isSubmitting"
                        Submitted="submitted"
                        ApplicationId="applicationId" />
            break;
    }
</div>

@code {
    private int currentStep;
    private PersonalInfo? personalInfo;
    private List<WorkEntry>? workEntries;
    private List<Reference>? references;
    private string coverLetter = string.Empty;
    private bool isSubmitting;
    private bool submitted;
    private int applicationId;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        if (personalInfo is null || workEntries is null || references is null)
            return;

        isSubmitting = true;
        try
        {
            var application = new JobApplication(
                personalInfo,
                new WorkHistory(workEntries),
                references,
                coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            submitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

