@namespace sv_f196e7562c6d441981ec843a2c602f4c.Components.Pages.Apply

<h5 class="mb-3">Work History</h5>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < entries.Count; i++)
{
    <WorkEntryForm Entry="entries[i]"
                   Index="i"
                   CanRemove="entries.Count > 1"
                   OnChanged="HandleEntryChanged"
                   OnRemove="HandleRemove" />
}

<button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<WorkEntry>? Entries { get; set; }
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> entries = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        entries = Entries?.Select(e => e).ToList()
            ?? new List<WorkEntry> { EmptyEntry() };
    }

    private static WorkEntry EmptyEntry() =>
        new(string.Empty, string.Empty, DateTime.Today, null, string.Empty);

    private void AddEntry() => entries.Add(EmptyEntry());

    private void HandleEntryChanged((int Index, WorkEntry Entry) args)
    {
        entries[args.Index] = args.Entry;
    }

    private void HandleRemove(int index)
    {
        if (entries.Count > 1)
            entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position must have a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(entries.ToList());
    }
}

