@namespace sv_f196e7562c6d441981ec843a2c602f4c.Components.Pages.Apply

<h5 class="mb-3">References</h5>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < references.Count; i++)
{
    <ReferenceForm Reference="references[i]"
                   Index="i"
                   CanRemove="references.Count > 2"
                   OnChanged="HandleReferenceChanged"
                   OnRemove="HandleRemove" />
}

@if (references.Count < 3)
{
    <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> references = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        references = References?.Select(r => r).ToList()
            ?? new List<Reference> { EmptyReference(), EmptyReference() };
    }

    private static Reference EmptyReference() =>
        new(string.Empty, string.Empty, string.Empty, string.Empty);

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(EmptyReference());
    }

    private void HandleReferenceChanged((int Index, Reference Reference) args)
    {
        references[args.Index] = args.Reference;
    }

    private void HandleRemove(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference must have at least a name and email.";
                return;
            }
        }

        await OnNext.InvokeAsync(references.ToList());
    }
}

