@namespace sv_f196e7562c6d441981ec843a2c602f4c.Components.Pages.Apply

<h5 class="mb-3">Cover Letter</h5>

<div class="mb-2">
    <textarea class="form-control" rows="10" maxlength="@MaxLength"
              value="@CoverLetter"
              @oninput="HandleInput"></textarea>
</div>
<div class="text-muted small mb-3">
    @(CoverLetter?.Length ?? 0) / @MaxLength characters
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void HandleInput(ChangeEventArgs e)
    {
        CoverLetter = (string?)e.Value ?? string.Empty;
        if (CoverLetter.Length > MaxLength)
            CoverLetter = CoverLetter[..MaxLength];
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetter);
    }
}

